      // jambe proche, griffes blanches
      d.ell(26, 54, 6.6, 7.4, Y);
      for (let i = 0; i < 3; i++) d.poly([[22 + i * 3.4, 62.4], [23.6 + i * 3.4, 57.8], [25.2 + i * 3.4, 62.4]], CW, { shiny: true });
