      d.ell(25, 55, 5.6, 4, FUR); foot(d, 21, 62.2, 1.1);
      for (let i = 0; i < 6; i++) d.poly([[18 + i * 3, 16], [13 + i * 3.6, 4 - (i % 2) * 3], [23 + i * 3, 11]], FUR);
