      d.deco.poly([[12.6, 14.8], [15.4, 14.8], [14, 16.4]], tint(T, -0.18));               // encolure
      d.deco.line(12.1, 14.9, 11.7, 21.4, 0.7, D); d.deco.line(15.9, 14.9, 16.3, 21.4, 0.7, D);   // bords de la veste
