      d.deco.rect(11.4, 19.4, 5.2, 2.6, tint(C.bagCol, -0.2)); d.deco.rect(13.6, 18.6, 0.8, 1.2, '#d8b040');
      d.deco.line(10.6, 15.2, 10.2, 14.4, 0.8, tint(C.bagCol, -0.3)); d.deco.line(17.4, 15.2, 17.8, 14.4, 0.8, tint(C.bagCol, -0.3));
