      // pointes qui retombent sur le front
      lock(d, C.hair, 9.6, 11.6, 10.4, 9.4, 6.6); lock(d, C.hair, 12.6, 15, 13.6, 9.8, 6.8); lock(d, C.hair, 16, 18, 17.4, 9.2, 6.8);
      // chaque pointe : un reflet et une ombre
