      for (const x of [22, 90]) { d.deco.rect(x, 48, 16, 14, '#1a1428'); d.deco.rect(x + 2, 50, 12, 10, '#c88aff'); d.deco.line(x + 8, 50, x + 8, 60, 0.8, '#1a1428'); d.deco.line(x + 2, 55, x + 14, 55, 0.8, '#1a1428'); }
