      d.deco.rect(60, 16, 6, 18, '#5a4a3a');
      for (const x of [14, 58]) { d.ell(x, 40, 4, 3, '#2a2a2e'); d.deco.ell(x, 40, 1.4, 1, '#6a6a70'); }
      d.tube([[36, 8], [36, 2], [44, -2]], 0.8, 0.6, '#3a3a40');
