      x.fillStyle = g; x.beginPath(); x.moveTo(bx - 6, by - 16); x.quadraticCurveTo(bx - 8.4, by - 8, bx - 6, by); x.lineTo(bx + 6, by); x.quadraticCurveTo(bx + 8.4, by - 8, bx + 6, by - 16); x.closePath(); x.fill();
