    const cg = x.createRadialGradient(52, 26, 4, 75, 44, 76); cg.addColorStop(0, '#d6a8ff'); cg.addColorStop(0.35, '#a670e0'); cg.addColorStop(0.8, '#6e3aa8'); cg.addColorStop(1, '#4a2280');
